/bin/bash -lc "node <<'NODE'
const base = 'http://localhost:3141/'
const first = await fetch(base)
const html = await first.text()
const action = html.match(/name=\"(\\"'$ACTION_ID_[a-f0-9]+)"/)
if (!action || !html.includes('"'Notifications are <"'!-- -->off'"')) throw new Error('Initial state or form action missing')
const form = new FormData()
form.set(action[1], '')
const submitted = await fetch(base, { method: 'POST', body: form, redirect: 'manual' })
const cookie = submitted.headers.get('set-cookie')
if (submitted.status "'!== 200 || submitted.headers.has('"'location') || "'!cookie?.includes('"'notifications=on')) {
  throw new Error("'`Unexpected action response: ${submitted.status}, ${submitted.headers.get('"'location')}, "'${cookie}`)
}
const updated = await fetch(base, { headers: { cookie: cookie.split('"';')[0] } })
const updatedHtml = await updated.text()
if ("'!updatedHtml.includes('"'Notifications are <"'!-- -->on'"')) throw new Error('Updated preference is not displayed')
console.log('PASS: off -> on; action response 200 with no Location header; page shows on')
NODE"

