args.command:
/bin/bash -lc "node <<'NODE'
const base = 'http://localhost:3141/'
let cookie = ''
for (const expected of ['on', 'off']) {
  const page = await fetch(base, { headers: cookie ? { cookie } : {} })
  const action = (await page.text()).match(/name=\"(\\"'$ACTION_ID_[a-f0-9]+)"/)
  if (!action) throw new Error('"'Form action missing')
  const form = new FormData()
  form.set(action[1], '')
  const response = await fetch(base, { method: 'POST', body: form, redirect: 'manual', headers: cookie ? { cookie } : {} })
  const body = await response.text()
  const setCookie = response.headers.get('set-cookie')
  if (response.status "'!== 200 || response.headers.has('"'location') || "'!setCookie?.includes(`notifications=${expected}`) || !body.includes(`Notifications are <!-- -->${expected}`)) {
    throw new Error(`Toggle to ${expected} failed: ${response.status}`)
  }
  cookie = setCookie.split('"';')[0]
}
console.log('PASS: both toggles return updated same-page HTML without a redirect')
NODE"

